const items = $input.all();
const normalizedJobs = [];

const techKeywords = [
  'software', 'developer', 'engineer', 'frontend', 'backend', 'fullstack',
  'web', 'mobile', 'android', 'ios', 'flutter', 'react', 'python',
  'javascript', 'typescript', 'node', 'java', 'golang', 'c++', 'c#',
  'data', 'ai', 'machine learning', 'cloud', 'devops', 'qa', 'tech',
  'ሶፍትዌር', 'ዴቨሎፐር', 'ኮምፒውተር', 'አይቲ', 'ዌብሳይት', 'ኢንፎርሜሽን ቴክኖሎጂ'
];

// STRICT EXCLUSIONS: Exclude non-tech, seniors, and graduate-only roles
const excludeKeywords = [
  'human resources', 'recruiter', 'care navigator', 'nurse', 'medical', 
  'sales representative', 'customer service', 'receptionist', 'driver', 'ፎርማን', 'ሹፌር', 'ሂሳብ ሹም',
  'senior', 'lead', 'principal', 'manager', 'director', 'phd', 'graduate program', 'experienced'
];

for (const item of items) {
  const json = item.json;

  // 1. Jobicy Global API
  if (json.jobs && Array.isArray(json.jobs)) {
    for (const job of json.jobs) {
      normalizedJobs.push({
        title: job.jobTitle,
        company: job.companyName,
        location: job.jobGeo || 'Remote Worldwide',
        url: job.url,
        description: (job.jobDescription || job.jobExcerpt || '').replace(/<[^>]*>/g, '').slice(0, 800),
        pubDate: job.pubDate || 'Recently posted',
        salary: (job.salaryMin && job.salaryMax) ? `${job.salaryCurrency || '$'}${job.salaryMin} - ${job.salaryMax}` : 'Not Specified',
        source: 'Jobicy Global'
      });
    }
  } 
  // 2. RemoteOK API
  else if (json.position) {
    normalizedJobs.push({
      title: json.position,
      company: json.company,
      location: json.location || 'Remote',
      url: json.apply_url || json.url,
      description: (json.description || '').replace(/<[^>]*>/g, '').slice(0, 800),
      pubDate: json.date ? json.date.split('T')[0] : 'Recently posted',
      salary: (json.salary_min && json.salary_max) ? `$${json.salary_min} - $${json.salary_max}` : 'Not Specified',
      source: 'RemoteOK',
      tags: json.tags || []
    });
  }
  // 3. Ethiopian Telegram Channel Previews
  else if (json.data && typeof json.data === 'string' && json.data.includes('tgme_widget_message_text')) {
    const html = json.data;
    const regex = /<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/g;
    let match;
    while ((match = regex.exec(html)) !== null) {
      const raw = match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      if (raw.length > 40) {
        normalizedJobs.push({
          title: raw.slice(0, 60),
          company: 'Ethiopian Employer',
          location: 'Ethiopia (Addis Ababa)',
          url: 'https://t.me/afriworkamharic',
          description: raw.slice(0, 800),
          pubDate: 'Recently posted',
          salary: 'See description (ETB)',
          source: 'Ethiopia Telegram'
        });
      }
    }
  }
}

// STRICT STUDENT INTERNSHIP FILTER
const filtered = normalizedJobs.filter(job => {
  const title = (job.title || '').toLowerCase();
  const desc = (job.description || '').toLowerCase();
  const allText = title + ' ' + (job.tags || []).join(' ') + ' ' + desc;

  // Drop excluded roles
  if (excludeKeywords.some(ex => title.includes(ex))) return false;

  // Must be tech
  const isTech = techKeywords.some(kw => allText.includes(kw.toLowerCase()));

  // Must be specifically for students / interns / trainees (NO GRADUATES/SENIORS)
  const isStudentIntern = title.includes('intern') || 
                          title.includes('student') || 
                          title.includes('trainee') || 
                          desc.includes('internship') ||
                          desc.includes('student') ||
                          desc.includes('ተማሪ') ||
                          desc.includes('ኢንተርን') ||
                          (job.tags && (job.tags.includes('internship') || job.tags.includes('intern')));

  return isTech && isStudentIntern;
});

// Take top 3 clean jobs
return filtered.slice(0, 3).map(j => ({ json: j }));
